#!/bin/sh
# Wave B end-to-end tests: f3dc CLI + the real Fortran engine.
# POSIX shell port of tests/e2e/test_waveb_e2e.py (7 checks, 1:1).
# Standalone-runnable from any CWD:  sh tests/e2e/test_waveb_e2e.sh
#
# PPM pixel statistics (the Python used tests/golden/check_image.py's
# read_ppm) are computed by an embedded mawk program below that parses
# the P3 token stream exactly the same way.  The glTF test fixture is
# generated byte-identically to the Python build_quad_gltf_text()
# (same packed float32/uint16 buffer, same json.dumps layout).
set -u

REPO_ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
# v3.0 Phase 2: these wave suites assert LEGACY renderer behaviour;
# the engine default is now v3, so pin the legacy path via the env
# fallback (an explicit --renderer flag would win over this).
export FORGE3D_RENDERER=legacy
BASE=$(basename -- "$0")

# F3DC resolution mirrors the Python: $F3DC, else bin/f3dc, else compiler/f3dc.
if [ "${F3DC:-}" ]; then
    F3DC_BIN=$F3DC
elif [ -f "$REPO_ROOT/bin/f3dc" ]; then
    F3DC_BIN=$REPO_ROOT/bin/f3dc
else
    F3DC_BIN=$REPO_ROOT/compiler/f3dc
fi

GOLDEN_SHA256=28b6a81dd052a740f3a395ea41b3e0dd37e02eeff585a56fa90e05ac7697cec1

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT INT TERM

# --- P3 PPM statistics program (mawk-compatible) -----------------------
cat > "$TMP/ppmstats.awk" <<'AWKEOF'
BEGIN {
    hdr=0; ncomp=0; npix=0; sum_all=0; max_sample=0
    distinct=0; distinct_greys=0; nonbg=0; has_black=0
    distfog_sum=0; covered_distinct=0; covered_n=0
    dom_count=0; fam_count=0; reg_sum=0; reg_n=0; npts=0
    if (dom_ch == "") dom_ch=-1
    if (rx0 == "") rx0=-1
    if (pts != "") {
        npts=split(pts, parr, ";")
        for (i=1; i<=npts; i++) { split(parr[i], xy, ","); px_[i]=xy[1]; py_[i]=xy[2]; psum[i]=-1 }
    }
}
function feed(tok,   v,comp,pix,r,g,b,x,y,key,i,mx,mn) {
    if (hdr < 4) {
        if (hdr==1) W=tok+0; else if (hdr==2) H=tok+0; else if (hdr==3) MAXV=tok+0
        hdr++; return
    }
    v=tok+0
    if (MAXV != 255) v=int(v*255/MAXV + 0.5)
    comp=ncomp%3; pix=int(ncomp/3)
    if (comp==0) { cr=v }
    else if (comp==1) { cg=v }
    else {
        r=cr; g=cg; b=v
        npix++; sum_all+=r+g+b
        if (r>max_sample) max_sample=r
        if (g>max_sample) max_sample=g
        if (b>max_sample) max_sample=b
        key=r","g","b
        if (!(key in cnt)) { cnt[key]=0; first[key]=pix; distinct++ }
        cnt[key]++
        if (r==g && g==b && !(key in grey_seen)) { grey_seen[key]=1; distinct_greys++ }
        if (r==0 && g==0 && b==0) has_black=1
        if (r!=bgr || g!=bgg || b!=bgb) {
            nonbg++; distfog_sum += (255-r)+(255-g)+(255-b)
            if (!(key in cov)) { cov[key]=1; covered_distinct++ }
            if (covered_n==0) { fr=r; fg=g; fb=b }
            covered_n++
        }
        if (dom_ch==0) { if (r>g+20 && r>b+20) dom_count++ }
        else if (dom_ch==1) { if (g>r+20 && g>b+20) dom_count++ }
        else if (dom_ch==2) { if (b>r+20 && b>g+20) dom_count++ }
        if (fam=="red") { if (r>g+10 && r>b+10) fam_count++ }
        else if (fam=="orange") { if (r>g+10 && g>b+5) fam_count++ }
        else if (fam=="green") { if (g>r+20 && g>b+20) fam_count++ }
        else if (fam=="blue") { if (b>r+20 && b>g+20) fam_count++ }
        else if (fam=="cyan") { if (g>r+20 && b>r+20) fam_count++ }
        else if (fam=="magenta") { if (r>g+15 && b>g+15) fam_count++ }
        else if (fam=="yellow") { if (r>b+20 && g>b+20) fam_count++ }
        else if (fam=="purple") { if (b>r+10 && r>g+10) fam_count++ }
        else if (fam=="pink") { if (r>g+15 && r>b+10) fam_count++ }
        else if (fam=="gray") {
            mx=r; if (g>mx) mx=g; if (b>mx) mx=b
            mn=r; if (g<mn) mn=g; if (b<mn) mn=b
            if (mx-mn<=12 && r>28) fam_count++
        }
        x=pix%W; y=int(pix/W)
        for (i=1; i<=npts; i++) if (x==px_[i] && y==py_[i]) psum[i]=r+g+b
        if (rx0>=0 && x>=rx0 && x<=rx1 && y>=ry0 && y<=ry1) { reg_sum+=r+g+b; reg_n++ }
    }
    ncomp++
}
{
    line=$0; sub(/#.*/, "", line)
    nt=split(line, toks, " ")
    for (t=1; t<=nt; t++) if (toks[t] != "") feed(toks[t])
}
END {
    bgkey=""; bgcount=-1; bgfirst=0
    for (k in cnt) {
        if (cnt[k]>bgcount || (cnt[k]==bgcount && first[k]<bgfirst)) {
            bgcount=cnt[k]; bgkey=k; bgfirst=first[k]
        }
    }
    split(bgkey, bgc, ",")
    domc=0; for (k in cnt) if (k!=bgkey && cnt[k]>=200) domc++
    printf "w=%d\nh=%d\nnpix=%d\nsum_all=%d\nmax_sample=%d\n", W, H, npix, sum_all, max_sample
    printf "mean=%.10f\n", (npix>0 ? sum_all/(npix*3) : 0)
    printf "distinct=%d\ndistinct_greys=%d\nnonbg=%d\nnonbg_mode=%d\nhas_black=%d\n", distinct, distinct_greys, nonbg, npix-bgcount, has_black
    printf "distfog_mean=%.10f\n", (nonbg>0 ? distfog_sum/nonbg : 0)
    printf "covered_n=%d\ncovered_distinct=%d\ncovered_r=%d\ncovered_g=%d\ncovered_b=%d\n", covered_n, covered_distinct, fr, fg, fb
    printf "bg_r=%d\nbg_g=%d\nbg_b=%d\nbg_count=%d\n", bgc[1], bgc[2], bgc[3], bgcount
    printf "dom_count=%d\nfam_count=%d\ndominant200=%d\n", dom_count, fam_count, domc
    printf "reg_mean=%.10f\nreg_n=%d\n", (reg_n>0 ? reg_sum/reg_n : 0), reg_n
    for (i=1; i<=npts; i++) printf "pix_%d_%d=%d\n", px_[i], py_[i], psum[i]
}
AWKEOF

# --- Differing-pixel counter for two P3 PPMs ----------------------------
cat > "$TMP/ppmdiff.awk" <<'AWKEOF'
BEGIN { file=1; hdr=0; ncomp=0; diff=0 }
function feed(tok,   v,comp,pix) {
    if (hdr < 4) {
        if (hdr==1) W=tok+0; else if (hdr==2) H=tok+0; else if (hdr==3) MAXV=tok+0
        hdr++; return
    }
    v=tok+0
    if (MAXV != 255) v=int(v*255/MAXV + 0.5)
    comp=ncomp%3; pix=int(ncomp/3)
    if (file==1) { s[ncomp]=v }
    else {
        if (comp==0) dflag=(v!=s[pix*3])
        else if (comp==1) { if (v!=s[pix*3+1]) dflag=1 }
        else { if (v!=s[pix*3+2]) dflag=1; if (dflag) diff++ }
    }
    ncomp++
}
{
    if (FNR==1 && NR!=1) { file=2; hdr=0; ncomp=0 }
    line=$0; sub(/#.*/, "", line)
    nt=split(line, toks, " ")
    for (t=1; t<=nt; t++) if (toks[t] != "") feed(toks[t])
}
END { print diff }
AWKEOF

PASS=0
FAIL=0
FAILED_THIS=0

fail_msg() { FAILED_THIS=1; echo "  # $*" >&2; }
assert_eq() { if [ "$1" != "$2" ]; then fail_msg "expected [$2], got [$1] ${3:-}"; fi }
assert_gt_int() { if [ "$1" -le "$2" ]; then fail_msg "expected $1 > $2 ${3:-}"; fi }
assert_ge_int() { if [ "$1" -lt "$2" ]; then fail_msg "expected $1 >= $2 ${3:-}"; fi }

stats() {
    _f=$1; shift
    STATS=$(awk -v bgr=25 -v bgg=25 -v bgb=35 "$@" -f "$TMP/ppmstats.awk" "$_f")
}
get() { printf '%s\n' "$STATS" | sed -n "s/^$1=//p"; }
sha_of() { sha256sum "$1" | awk '{print $1}'; }

render() {
    _work=$TMP/$1
    mkdir -p "$_work"
    printf '%s' "$2" > "$_work/scene.f3d"
    (cd "$REPO_ROOT" && "$F3DC_BIN" run "$_work/scene.f3d" -o "$_work/build") \
        >"$_work/run.out" 2>"$_work/run.err"
    _rc=$?
    if [ "$_rc" -ne 0 ]; then
        fail_msg "render $1 exited $_rc: $(cat "$_work/run.err")"; return 1
    fi
    if [ ! -f "$_work/build/output_render.ppm" ]; then
        fail_msg "no output_render.ppm for $1"; return 1
    fi
    return 0
}

run_check() {
    _name=$1; shift
    FAILED_THIS=0
    "$@"
    if [ "$FAILED_THIS" -eq 0 ]; then
        PASS=$((PASS + 1)); echo "ok $_name"
    else
        FAIL=$((FAIL + 1)); echo "not ok $_name"
    fi
}

# --- setUpClass equivalent ---------------------------------------------
if command -v gfortran >/dev/null 2>&1 && command -v make >/dev/null 2>&1; then
    if ! make -C "$REPO_ROOT" >"$TMP/make.log" 2>&1; then
        echo "make failed:" >&2; cat "$TMP/make.log" >&2
        echo "$BASE: FAIL (setup: make failed)"
        exit 1
    fi
fi
if [ ! -f "$REPO_ROOT/bin/engine3d" ]; then
    echo "SKIP: bin/engine3d missing and gfortran/make unavailable to build it: cannot run Wave B e2e" >&2
    echo "$BASE: SKIP (0 checks)"
    exit 0
fi

# A red indexed quad (-3..3 x -2..2, XY plane) as .gltf text; single
# data-URI buffer, baseColorFactor makes every triangle red.  Bytes are
# identical to the Python build_quad_gltf_text(): float32 LE positions
# (-3,-2,0) (3,-2,0) (3,2,0) (-3,2,0), uint16 LE indices 0 1 2 0 2 3.
build_quad_gltf_text() {
    printf '\000\000\100\300\000\000\000\300\000\000\000\000\000\000\100\100\000\000\000\300\000\000\000\000\000\000\100\100\000\000\000\100\000\000\000\000\000\000\100\300\000\000\000\100\000\000\000\000\000\000\001\000\002\000\000\000\002\000\003\000' > "$TMP/quad.bin"
    _b64=$(base64 -w 0 "$TMP/quad.bin")
    printf '%s' "{\"asset\": {\"version\": \"2.0\"}, \"scene\": 0, \"scenes\": [{\"nodes\": [0]}], \"nodes\": [{\"mesh\": 0}], \"meshes\": [{\"primitives\": [{\"attributes\": {\"POSITION\": 0}, \"indices\": 1, \"mode\": 4, \"material\": 0}]}], \"materials\": [{\"pbrMetallicRoughness\": {\"baseColorFactor\": [1.0, 0.0, 0.0, 1.0]}}], \"bufferViews\": [{\"buffer\": 0, \"byteOffset\": 0, \"byteLength\": 48, \"target\": 34962}, {\"buffer\": 0, \"byteOffset\": 48, \"byteLength\": 12, \"target\": 34963}], \"accessors\": [{\"bufferView\": 0, \"componentType\": 5126, \"type\": \"VEC3\", \"count\": 4}, {\"bufferView\": 1, \"componentType\": 5123, \"type\": \"SCALAR\", \"count\": 6}], \"buffers\": [{\"byteLength\": 60, \"uri\": \"data:application/octet-stream;base64,${_b64}\"}]}"
}

# -- row 19: glTF ---------------------------------------------------------

test_row19_gltf_quad_renders_nonflat() {
    mkdir -p "$TMP/gltf_quad"
    build_quad_gltf_text > "$TMP/gltf_quad/quad.gltf"
    _src='scene size 160 120
camera at 0 0 10 look 0 0 0
load "quad.gltf" quad at 0,0,0
render still
'
    render gltf_quad "$_src" || return
    stats "$TMP/gltf_quad/build/output_render.ppm"
    assert_ge_int "$(get distinct)" 2 "gltf quad image is flat"
    assert_gt_int "$(get nonbg)" 100 "gltf quad covers too few pixels"
}

# -- rows 23 / 24 / 29: sprite + text ---------------------------------------

test_rows23_24_29_sprite_and_text_render() {
    _src='scene size 320 240
camera at 6 4 9 look 0 0 0
cube hero red at 0 0 0 size 2
sphere ball blue at 3 0 0 radius 1
sprite star at 0,3,0 size 1 color yellow
text label "FORGE 3D" at -3,2,0 size 1 color white
render still
'
    render sprite_text "$_src" || return
    stats "$TMP/sprite_text/build/output_render.ppm"
    assert_ge_int "$(get distinct)" 10 "sprite+text image has too few colours"
    assert_gt_int "$(get nonbg)" 1000 "sprite+text covers too few pixels"
}

# -- row 32: particles ---------------------------------------------------------

PARTICLES_SRC='scene size 160 120
camera at 6 4 9 look 0 0 0
cube hero red at 0 0 0 size 2
particles fountain at 0,2,0 count 100 life 2 speed 3 size 0.2 color orange spread 0.5 gravity 9 seed 7
render still
'

test_row32_particles_fountain_nonflat_and_deterministic() {
    render particles_a "$PARTICLES_SRC" || return
    render particles_b "$PARTICLES_SRC" || return
    stats "$TMP/particles_a/build/output_render.ppm"
    assert_ge_int "$(get distinct)" 2 "particles image is flat"
    assert_gt_int "$(get nonbg)" 100 "particles cover too few pixels"
    assert_eq "$(sha_of "$TMP/particles_a/build/output_render.ppm")" \
              "$(sha_of "$TMP/particles_b/build/output_render.ppm")" \
              "particles render must be deterministic"
}

# -- row 17: keyframes -------------------------------------------------------------

test_row17_keys_animation_frames_differ() {
    _src='scene size 160 120
camera at 0 2 8 look 0 0 0
cube hero red at -2,0,0 size 1
sphere ball blue at 3,0,0 radius 1
keys hero duration 2 loop pingpong
key hero at 0 pos -2,0,0 rot 0,0,0 scale 1
key hero at 2 pos -2,1,0 rot 0,90,0 scale 1.5 ease smooth
spin ball duration 2 fps 2
render duration 2 fps 2
'
    render keys_anim "$_src" || return
    set -- "$TMP"/keys_anim/build/output_render_*.ppm
    if [ ! -f "$1" ]; then fail_msg "no animation frames produced"; return; fi
    assert_ge_int "$#" 3 "expected >= 3 animation frames"
    _first=$1
    for _last do :; done
    if cmp -s "$_first" "$_last"; then
        fail_msg "first and last animation frames are identical"
    fi
}

# -- row 16: directional shadow -------------------------------------------------------

test_row16_directional_shadow_darkens_ground() {
    _pre='scene "dctl" size 160 120 background black shadow '
    _post='
camera at 0 -6 12 look 0 -1 0
plane ground gray at 0 -2 0 size 12 material standard metalness 0 roughness 0.95
cube hero white at 0 0 0 size 2 material standard metalness 0 roughness 0.8
render still
'
    render dshadow_on "${_pre}on${_post}" || return
    render dshadow_off "${_pre}off${_post}" || return
    _diff=$(awk -f "$TMP/ppmdiff.awk" "$TMP/dshadow_on/build/output_render.ppm" "$TMP/dshadow_off/build/output_render.ppm")
    assert_ge_int "$_diff" 100 "only $_diff pixels differ between shadow on/off"
    stats "$TMP/dshadow_on/build/output_render.ppm" -v pts=76,68
    _on=$(get pix_76_68)
    stats "$TMP/dshadow_off/build/output_render.ppm" -v pts=76,68
    _off=$(get pix_76_68)
    if [ $((_off - _on)) -le 100 ]; then
        fail_msg "ground pixel (76,68) not darkened enough: on=$_on off=$_off"
    fi
}

# -- golden regression ------------------------------------------------------------------

test_golden_legacy_no_arg_engine() {
    _work=$TMP/golden_noarg
    mkdir -p "$_work"
    (cd "$_work" && "$REPO_ROOT/bin/engine3d") >"$_work/out.txt" 2>"$_work/err.txt"
    assert_eq "$?" 0 "engine output: $(cat "$_work/out.txt" "$_work/err.txt")"
    if [ ! -f "$_work/output_render.ppm" ]; then fail_msg "no output_render.ppm from no-arg engine"; return; fi
    assert_eq "$(sha_of "$_work/output_render.ppm")" "$GOLDEN_SHA256" "golden hash"
}

test_golden_one_line_cube_cli_render() {
    render golden_cube 'cube
' || return
    assert_eq "$(sha_of "$TMP/golden_cube/build/output_render.ppm")" "$GOLDEN_SHA256" "golden hash"
}

run_check test_row19_gltf_quad_renders_nonflat test_row19_gltf_quad_renders_nonflat
run_check test_rows23_24_29_sprite_and_text_render test_rows23_24_29_sprite_and_text_render
run_check test_row32_particles_fountain_nonflat_and_deterministic test_row32_particles_fountain_nonflat_and_deterministic
run_check test_row17_keys_animation_frames_differ test_row17_keys_animation_frames_differ
run_check test_row16_directional_shadow_darkens_ground test_row16_directional_shadow_darkens_ground
run_check test_golden_legacy_no_arg_engine test_golden_legacy_no_arg_engine
run_check test_golden_one_line_cube_cli_render test_golden_one_line_cube_cli_render

TOTAL=$((PASS + FAIL))
if [ "$FAIL" -eq 0 ]; then
    echo "$BASE: PASS ($TOTAL checks)"
    exit 0
else
    echo "$BASE: FAIL ($FAIL of $TOTAL checks failed)"
    exit 1
fi
